deral Government\ntotal_outside = 614968\n\n# Non-service-related obligations\nnon_service_related = total_outside - service_related\nprint(\"\\nTotal outside obligations:\", total_outside)\nprint(\"Non-service-related:\", non_service_related)\n\n# Calculate percentage\npercentage = (non_service_related / total_outside) * 100\nprint(f\"\\nPercentage NOT service-related: {percentage:.2f}%\")\nprint(f\"Rounded to nearest whole number: {round(percentage)}%\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
